import{_ as a,o as d,c as o,a2 as e}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"প্রতিলিপি দর্পণ অন্যতল প্রত্নতত্ত্ব পরিকল্পনা","description":"","frontmatter":{},"headers":[],"relativePath":"bn/85-复制镜异地考古方案.md","filePath":"bn/85-复制镜异地考古方案.md"}'),r={name:"bn/85-复制镜异地考古方案.md"};function l(h,t,i,n,u,q){return d(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="প্রতিলিপি-দর্পণ-অন্যতল-প্রত্নতত্ত্ব-পরিকল্পনা" tabindex="-1">প্রতিলিপি দর্পণ অন্যতল প্রত্নতত্ত্ব পরিকল্পনা <a class="header-anchor" href="#প্রতিলিপি-দর্পণ-অন্যতল-প্রত্নতত্ত্ব-পরিকল্পনা" aria-label="Permalink to &quot;প্রতিলিপি দর্পণ অন্যতল প্রত্নতত্ত্ব পরিকল্পনা&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>85</td></tr><tr><td>মডিউল</td><td>আন্তঃ-তল মিথস্ক্রিয়া ও সময় নিয়ম</td></tr><tr><td>মূল কীওয়ার্ড</td><td>প্রতিলিপি দর্পণ, অন্যতল প্রত্নতত্ত্ব, স্থান স্ক্যান, প্রতিলিপি পুনর্নির্মাণ, শূন্য সংস্পর্শ</td></tr></tbody></table><h2 id="_1-পরিকল্পনার-সারসংক্ষেপ" tabindex="-1">1. পরিকল্পনার সারসংক্ষেপ <a class="header-anchor" href="#_1-পরিকল্পনার-সারসংক্ষেপ" aria-label="Permalink to &quot;1. পরিকল্পনার সারসংক্ষেপ&quot;">​</a></h2><p>প্রতিলিপি দর্পণ অন্যতল প্রত্নতত্ত্ব পরিকল্পনা হলো হেংইয়ান-ঝৌর আন্তঃ-তল ও সময় প্রত্যাবর্তন প্রত্নতত্ত্বের মানক প্রযুক্তিগত পরিকল্পনা, যার মূল চিন্তা হলো &quot;প্রবেশ করব না, সংস্পর্শ করব না, শুধুমাত্র প্রতিলিপি করব&quot;। ঐতিহ্যবাহী প্রত্নতত্ত্বে প্রত্নতত্ত্ব কর্মীদের নিজেরাই প্রত্নতত্ত্ব স্থানে প্রবেশ করে খনন করতে হয়, যা অনিবার্যভাবে স্থানে ভৌত হস্তক্ষেপ ও পরিবেশ দূষণ সৃষ্টি করে। প্রতিলিপি দর্পণ পরিকল্পনা则 স্থান আইন প্রযুক্তির মাধ্যমে, মূল বস্তুর সাথে সম্পূর্ণরূপে সংস্পর্শ না করেই, প্রত্নতত্ত্বের লক্ষ্যকে সম্পূর্ণরূপে অন্যতলের বিচ্ছিন্ন স্থানে প্রতিলিপি করে, তারপর বিচ্ছিন্ন স্থানের মধ্যে সমস্ত প্রত্নতত্ত্ব অপারেশন সম্পাদন করে।</p><p>&quot;অন্যতল&quot; হলো এই পরিকল্পনার মূল বৈশিষ্ট্য। প্রতিলিপি অপারেশন লক্ষ্য তল বা লক্ষ্য সময়কালের নিকটবর্তী নিরাপদ অঞ্চলে সম্পন্ন হয়, কিন্তু প্রতিলিপির তৈরি ও পরবর্তী প্রত্নতত্ত্ব গবেষণা সম্পূর্ণরূপে লক্ষ্য থেকে সম্পূর্ণ বিচ্ছিন্ন স্বাধীন স্থানে সম্পাদিত হয়। এর মানে হলো প্রত্নতত্ত্ব কর্মীরা শুরু থেকে শেষ পর্যন্ত লক্ষ্য অঞ্চলে প্রবেশ করতে হবে না, এমনকি লক্ষ্য তলে প্রবেশ করতেও হবে না — সম্পূর্ণ প্রত্নতত্ত্ব প্রক্রিয়া নিজের তলের বিচ্ছিন্ন স্থানে দূরবর্তীভাবে সম্পন্ন করা যায়।</p><p>প্রতিলিপি দর্পণ অন্যতল প্রত্নতত্ত্ব পরিকল্পনার প্রযুক্তিগত ভিত্তি হলো স্থান আইন নিয়ন্ত্রণ ব্যবস্থার উচ্চ-স্তরের প্রয়োগ। শুধুমাত্র স্থান আইন নিয়ন্ত্রণ ব্যবস্থার চতুর্থ স্তর (ফা-কুং জিং) বা তার বেশি সাধনকারী, অথবা সমান প্রযুক্তিগত স্তরের প্রতিলিপি দর্পণ বাহক যুক্ত করা, উচ্চ-নির্ভুল প্রতিলিপি অপারেশন সম্পাদন করতে সক্ষম। বর্তমানে হেংইয়ান-ঝৌ প্রতিলিপি দর্পণের প্রকৌশলগত বাল্ক উৎপাদন বাস্তবায়ন করেছে, মানক ধরনের প্রতিলিপি দর্পণ ডিভাইস তৃতীয় স্তর (হুয়া-কুং জিং) সাধনকারী দ্বারা পরিচালিত হয়ে স্বাভাবিক প্রত্নতত্ত্ব কাজ সম্পন্ন করতে পারে।</p><h2 id="_2-প্রতিলিপি-দর্পণের-প্রযুক্তিগত-নীতি" tabindex="-1">2. প্রতিলিপি দর্পণের প্রযুক্তিগত নীতি <a class="header-anchor" href="#_2-প্রতিলিপি-দর্পণের-প্রযুক্তিগত-নীতি" aria-label="Permalink to &quot;2. প্রতিলিপি দর্পণের প্রযুক্তিগত নীতি&quot;">​</a></h2><p>প্রতিলিপি দর্পণের মূল অংশ হলো &quot;স্থান আইন স্ক্যান অ্যারে&quot; এবং &quot;কণা অবস্থা পুনর্নির্মাণকারী&quot;। এর কাজের প্রক্রিয়া তিনটি পর্যায়ে বিভক্ত:</p><h3 id="_2-1-স্থান-স্ক্যান-পর্যায়" tabindex="-1">2.1 স্থান স্ক্যান পর্যায় <a class="header-anchor" href="#_2-1-স্থান-স্ক্যান-পর্যায়" aria-label="Permalink to &quot;2.1 স্থান স্ক্যান পর্যায়&quot;">​</a></h3><p>প্রতিলিপি দর্পণ স্থাপন সম্পন্ন হওয়ার পর, প্রথমে লক্ষ্য অঞ্চলে সর্বত্র স্থান আইন স্ক্যান করা হয়। স্ক্যান অ্যারে উচ্চ-ফ্রিকোয়েন্সি স্থান তরঙ্গ নির্গত করে, যা লক্ষ্য অঞ্চলের সমস্ত পদার্থ ও শক্তি কাঠামোকে ভেদ করে, প্রতিটি কণার অবস্থান, ভরবেগ, স্পিন, শক্তি অবস্থা ইত্যাদি সমস্ত কোয়ান্টাম প্যারামিটার রেকর্ড করে। একই সাথে, স্ক্যান অ্যারে লক্ষ্য অঞ্চলের শক্তি ক্ষেত্রের বিতরণ, আইন প্যারামিটারের ওঠানামা ও চেতনার ছাপের অবশিষ্টাংশও অনুসন্ধান করে।</p><p>স্ক্যান প্রক্রিয়া সম্পূর্ণরূপে নিষ্ক্রিয় — স্থান তরঙ্গ পদার্থকে ভেদ করার সময় এর কোনো অবস্থা পরিবর্তন করে না, তাই প্রত্নতত্ত্ব স্থানে কোনো হস্তক্ষেপ সৃষ্টি করে না। স্ক্যানের নির্ভুলতা প্রতিলিপি দর্পণের প্রযুক্তিগত স্তরের উপর নির্ভর করে, মানক ধরনের ডিভাইসের স্ক্যান নির্ভুলতা উপ-পরমাণু স্তর, উচ্চ-স্তরের গবেষণাধরনের ডিভাইস কোয়ার্ক স্তরে পৌঁছাতে পারে।</p><h3 id="_2-2-ডেটা-ট্রান্সমিশন-পর্যায়" tabindex="-1">2.2 ডেটা ট্রান্সমিশন পর্যায় <a class="header-anchor" href="#_2-2-ডেটা-ট্রান্সমিশন-পর্যায়" aria-label="Permalink to &quot;2.2 ডেটা ট্রান্সমিশন পর্যায়&quot;">​</a></h3><p>স্ক্যান দ্বারা প্রাপ্ত বিশাল পরিমাণ ডেটা অ্যাঙ্কর নেটওয়ার্কের এনক্রিপ্টেড চ্যানেলের মাধ্যমে বিচ্ছিন্ন স্থানে ট্রান্সমিট করা হয়। ডেটা ট্রান্সমিশন &quot;কোয়ান্টাম স্টেট এনক্রিপশন প্রোটোকল&quot; ব্যবহার করে, যা নিশ্চিত করে যে ট্রান্সমিশন প্রক্রিয়াতে ডেটা চুরি বা বিকৃত হয় না। ডেটার পরিমাণ অত্যন্ত বিশাল — একটি সাধারণ ঘরের আকারের অঞ্চলের সম্পূর্ণ স্ক্যান ডেটার পরিমাণ প্রায় 10 এর 30 ঘাত বাইট, যা যুক্তিসঙ্গত সময়ে ট্রান্সমিশন সম্পন্ন করতে অ্যাঙ্কর নেটওয়ার্কের উচ্চ-মাত্রিক ডেটা চ্যানেলের সাহায্য লাগে।</p><h3 id="_2-3-প্রতিলিপি-পুনর্নির্মাণ-পর্যায়" tabindex="-1">2.3 প্রতিলিপি পুনর্নির্মাণ পর্যায় <a class="header-anchor" href="#_2-3-প্রতিলিপি-পুনর্নির্মাণ-পর্যায়" aria-label="Permalink to &quot;2.3 প্রতিলিপি পুনর্নির্মাণ পর্যায়&quot;">​</a></h3><p>বিচ্ছিন্ন স্থানের কণা অবস্থা পুনর্নির্মাণকারী ডেটা গ্রহণ করার পর, স্ক্যান রেকর্ডের সুনির্দিষ্ট প্যারামিটার অনুযায়ী, বিচ্ছিন্ন স্থানে কণা অনুযায়ী লক্ষ্য অঞ্চলের সম্পূর্ণ প্রতিলিপি পুনর্নির্মাণ করে। পুনর্নির্মাণ প্রক্রিয়া নিচের স্তরের কণা থেকে শুরু করে, স্তরে স্তরে উপরের দিকে পরমাণু, অণু, পদার্থ কাঠামো, শক্তি ক্ষেত্র ও চেতনার ছাপ তৈরি করে। পুনর্নির্মাণ সম্পন্ন হওয়ার পর, প্রতিলিপি ও মূল বস্তু ভৌত স্তরে সম্পূর্ণ অভিন্ন — প্রত্নবস্তুর উপাদান, কাঠামো, পৃষ্ঠের চিহ্ন, অভ্যন্তরীণ ক্ষতি, এমনকি অবশিষ্ট শক্তি ক্ষেত্র ও চেতনার ছাপ সহ।</p><p>বিশেষভাবে উল্লেখ করা দরকার যে, প্রতিলিপিতে থাকা &quot;চেতনার ছাপ&quot; হলো মূল বস্তু দীর্ঘকালীন অস্তিত্বের প্রক্রিয়াতে শোষিত পরিবেশের চেতনার অবশিষ্টাংশ, প্রকৃত চেতনা বস্তু নয়। প্রতিলিপির স্বায়ত্তশাসিত চেতনা নেই, এবং কোনো নতুন চেতনা কার্যকলাপ তৈরি করবে না। এই বিষয়টি সিম্বায়োসিস আদালতের আইনি ব্যাখ্যা দ্বারা নিশ্চিত করা হয়েছে, প্রতিলিপি &quot;জীবন&quot; শ্রেণীর অন্তর্গত নয়, প্রতিলিপির গবেষণা জীবন নৈতিক সমস্যা জড়িত নয়।</p><h2 id="_3-প্রতিলিপি-দর্পণের-শ্রেণীবিভাগ-ও-প্রযোজ্য-পরিস্থিতি" tabindex="-1">3. প্রতিলিপি দর্পণের শ্রেণীবিভাগ ও প্রযোজ্য পরিস্থিতি <a class="header-anchor" href="#_3-প্রতিলিপি-দর্পণের-শ্রেণীবিভাগ-ও-প্রযোজ্য-পরিস্থিতি" aria-label="Permalink to &quot;3. প্রতিলিপি দর্পণের শ্রেণীবিভাগ ও প্রযোজ্য পরিস্থিতি&quot;">​</a></h2><p>প্রতিলিপির পরিসর, নির্ভুলতা ও কার্যকারিতার অনুযায়ী, প্রতিলিপি দর্পণ নিম্নলিখিত চারটি শ্রেণীতে বিভক্ত:</p><table tabindex="0"><thead><tr><th>মডেল</th><th>প্রতিলিপির পরিসর</th><th>নির্ভুলতার স্তর</th><th>প্রযোজ্য পরিস্থিতি</th><th>অপারেটরের সাধনার প্রয়োজনীয়তা</th></tr></thead><tbody><tr><td>মানক ধরন (CM-S)</td><td>সর্বোচ্চ 100 ঘনমিটার</td><td>উপ-পরমাণু স্তর</td><td>একক প্রত্নবস্তু, ছোট ধ্বংসস্তূপের স্বাভাবিক প্রত্নতত্ত্ব</td><td>হুয়া-কুং জিং (তৃতীয় স্তর)</td></tr><tr><td>সম্প্রসারিত ধরন (CM-E)</td><td>সর্বোচ্চ 10000 ঘনমিটার</td><td>উপ-পরমাণু স্তর</td><td>বড় ভবন, গ্রাম-স্তরের ধ্বংসস্তূপের সামগ্রিক প্রতিলিপি</td><td>ফা-কুং জিং (চতুর্থ স্তর)</td></tr><tr><td>গবেষণাধরন (CM-R)</td><td>সর্বোচ্চ 1000 ঘনমিটার</td><td>কোয়ার্ক স্তর</td><td>অতি উচ্চ নির্ভুলতার বিশ্লেষণ প্রয়োজনীয় মূল্যবান প্রত্নবস্তুর গবেষণা</td><td>ফা-কুং জিং (চতুর্থ স্তর)+ ডিডাকশন ইটারেশন ব্যবস্থার তৃতীয় স্তর</td></tr><tr><td>বিশেষ সজ্জিত ধরন (CM-X)</td><td>সর্বোচ্চ 1 ঘনকিলোমিটার</td><td>উপ-পরমাণু স্তর</td><td>শহর-স্তরের ধ্বংসস্তূপ গোষ্ঠীর উদ্ধারমূলক সামগ্রিক প্রতিলিপি</td><td>ইয়ান-কুং জিং (পঞ্চম স্তর) বা বাহক সহায়তা</td></tr></tbody></table><p>আইন ভাঙা তল ইত্যাদি বিশেষ পরিবেশের জন্য, বিশেষভাবে পরিবর্তিত &quot;আইন সামঞ্জস্যপূর্ণ প্রতিলিপি দর্পণ&quot; ব্যবহার করতে হবে, যার স্ক্যান অ্যারে অস্থির আইন পরিবেশের সাথে খাপ খাইয়ে নিতে সক্ষম, নিশ্চিত করে যে আইনের ওঠানামার মধ্যেও সঠিক স্ক্যান ডেটা পাওয়া যায়।</p><h2 id="_4-অন্যতল-প্রত্নতত্ত্বের-অপারেশনের-মূল-বিষয়" tabindex="-1">4. অন্যতল প্রত্নতত্ত্বের অপারেশনের মূল বিষয় <a class="header-anchor" href="#_4-অন্যতল-প্রত্নতত্ত্বের-অপারেশনের-মূল-বিষয়" aria-label="Permalink to &quot;4. অন্যতল প্রত্নতত্ত্বের অপারেশনের মূল বিষয়&quot;">​</a></h2><p>প্রতিলিপি দর্পণ অন্যতল প্রত্নতত্ত্ব পরিকল্পনা বাস্তব অপারেশনে নিম্নলিখিত মূল বিষয়গুলো লক্ষ্য রাখা দরকার:</p><ol><li><p><strong>স্থাপনের অবস্থান নির্বাচন</strong>: প্রতিলিপি দর্পণ লক্ষ্য অঞ্চলের আইনি নিরাপদ দূরত্বের বাইরে স্থাপন করতে হবে, যা既 স্ক্যানের পরিসর লক্ষ্যকে কভার করে নিশ্চিত করে, আবার ডিভাইস নিজেই লক্ষ্য অঞ্চলে আইনি ব্যাঘাত সৃষ্টি করা থেকে বিরত রাখে। নিরাপদ দূরত্ব সাধারণত লক্ষ্য অঞ্চলের সর্বোচ্চ মাপের 3 গুণ বা তার বেশি হয়।</p></li><li><p><strong>প্রতিলিপির সময় নির্বাচন</strong>: সময় প্রত্যাবর্তন প্রত্নতত্ত্বের জন্য, প্রতিলিপি দর্পণের স্থাপন ও স্ক্যান লক্ষ্য সময়কালের &quot;আইনি শান্তিকালে&quot; সম্পাদন করতে হবে, বড় ঐতিহাসিক ঘটনা ঘটার মুহূর্তে প্রতিলিপি অপারেশন সম্পাদন করা এড়ানো উচিত — এই সময়ে কার্য-কারণ শৃঙ্খলার ঘনত্ব অত্যন্ত বেশি, প্রতিলিপি অপারেশনের শক্তি খরচ ব্যাপকভাবে বাড়বে, এবং কার্য-কারণ লাইনে ক্ষীণ ব্যাঘাত সৃষ্টি করতে পারে।</p></li><li><p><strong>প্রতিলিপির সম্পূর্ণতা যাচাই</strong>: প্রতিলিপি পুনর্নির্মাণ সম্পন্ন হওয়ার পর, অবশ্যই &quot;প্রতিলিপি-মূল বস্তুর সামঞ্জস্য যাচাই&quot; সম্পাদন করতে হবে। যাচাইের পদ্ধতি হলো প্রতিলিপির দ্বিতীয়বার স্ক্যান করা, স্ক্যান ডেটাকে মূল স্ক্যান ডেটার সাথে কণা অনুযায়ী তুলনা করা, ত্রুটির হার অবশ্যই 10 এর ঋণাত্মক 12 ঘাতের নিচে হতে হবে। যদি ত্রুটির হার সীমা অতিক্রম করে, অবশ্যই প্রতিলিপি ধ্বংস করে পুনরায় প্রতিলিপি করতে হবে।</p></li><li><p><strong>বহু-রাউন্ড প্রতিলিপির কৌশল</strong>: অতি বড় ধ্বংসস্তূপের জন্য, একক প্রতিলিপি সম্পূর্ণ অঞ্চল কভার করতে না পারতে পারে। এই সময়ে &quot;অঞ্চলভিত্তিক বহু-রাউন্ড প্রতিলিপি&quot; কৌশল ব্যবহার করা হয়, ধ্বংসস্তূপকে একাধিক অঞ্চলে বিভক্ত করে পৃথকভাবে প্রতিলিপি করা, তারপর বিচ্ছিন্ন স্থানে সংযুক্ত করা হয়। সংযুক্ত করার সময় নিশ্চিত করতে হবে যে সংলগ্ন অঞ্চলের সীমানায় কণার অবস্থা নিরবিচ্ছিন্নভাবে সংযুক্ত হয়, কোনো আইনি স্তরময়তা দেখা যায় না।</p></li></ol><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>প্রতিলিপি দর্পণ অন্যতল প্রত্নতত্ত্ব পরিকল্পনা হলো হেংইয়ান-ঝৌর স্থান আইন নিয়মের প্রকৌশলগত প্রয়োগের আদর্শ। এটি &quot;শূন্য সংস্পর্শ প্রতিলিপি, অন্যতল গবেষণা&quot; প্রযুক্তিগত পথের মাধ্যমে, মূলত ঐতিহ্যবাহী প্রত্নতত্ত্বে &quot;জ্ঞান অর্জন&quot; ও &quot;স্থান সুরক্ষা&quot; এর মধ্যে দ্বন্দ্ব সমাধান করে। এই পরিকল্পনা শুধুমাত্র প্রত্নতত্ত্বের দক্ষতা ব্যাপকভাবে বাড়ায় না, আরও গুরুত্বপূর্ণ হলো, এটি নিশ্চিত করে যে প্রতিটি প্রত্নতত্ত্ব লক্ষ্য সভ্যতা ও ঐতিহাসিক স্থানে কোনো চিহ্ন রাখবে না — সত্যিকারের অর্থে &quot;আমি হালকা হয়ে চলে গেছি, যেমন আমি হালকা হয়ে এসেছি&quot;।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>84-প্রত্নতত্ত্ব চুক্তি মূল নীতি</li><li>86-বিচ্ছিন্ন স্থান কম দূষণ প্রক্রিয়া</li><li>63-প্রতিলিপি দর্পণ প্রযুক্তিগত নীতি</li></ul>',27)])])}const s=a(r,[["render",l]]);export{p as __pageData,s as default};
